 long monthTotal(YearMonth ym,int category){long total=0;Iterator<String> it=records.keys();while(it.hasNext()){LocalDate d=LocalDate.parse(it.next());if(!YearMonth.from(d).equals(ym))continue;JSONObject r=rec(d);if(category<0||(work(d,r)?0:1)==category)total+=mins(d,r);}return total;}
 String anomalyReport(YearMonth ym){
  StringBuilder out=new StringBuilder();LocalDate end=ym.atEndOfMonth().isAfter(Rules.today())?Rules.today():ym.atEndOfMonth();
  for(LocalDate d=ym.atDay(1);!d.isAfter(end);d=d.plusDays(1)){
   JSONObject r=rec(d);if(!work(d,r))continue;String state=status(d,r);
   if(isLeave(r)&&"全天请假".equals(state))continue;
   if(!"已确认".equals(state))out.append(d).append("  ").append(state).append("\\n");
  }
  return out.length()==0?"本月暂无待处理异常。":out.toString();
 }
